export function useConfirmationDialog() {
  const [controller] = useState(() => new ConfirmationController());
  const request = useSyncExternalStore(
    controller.subscribe,
    controller.getSnapshot,
    controller.getSnapshot
  );

  useEffect(
    () => () => {
      controller.dispose();
