export function AppSwitch({
  checked,
  onCheckedChange,
  disabled = false,
  label,
  description
}: {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  disabled?: boolean;
  label: string;
  description?: string;
}) {
  const stateLabel = checked ? "已开启" : "已关闭";

  return (
    <Pressable
      accessibilityRole="switch"
      accessibilityLabel={label}
      accessibilityHint={description}
      accessibilityState={{ checked, disabled }}
      accessibilityValue={{ text: stateLabel }}
      disabled={disabled}
      onPress={() => {
        onCheckedChange(!checked);
      }}
      style={({ pressed }) => [
        styles.root,
        disabled ? styles.disabled : null,
        pressed ? styles.pressed : null
      ]}
    >
      <View style={styles.copy} pointerEvents="none">
        <Text weight="semibold">{label}</Text>
        {description ? (
          <Text tone={disabled ? "disabled" : "muted"} size="xs">
            {description}
          </Text>
        ) : null}
      </View>
      <View
        pointerEvents="none"
        style={[
          styles.track,
          checked ? styles.trackChecked : styles.trackUnchecked
        ]}
      >
        <NativeText
          allowFontScaling={false}
          style={[
            styles.stateText,
            checked ? styles.stateTextStart : styles.stateTextEnd
          ]}
        >
          {checked ? "开" : "关"}
        </NativeText>
        <View
          style={[
            styles.thumb,
            checked ? styles.thumbChecked : styles.thumbUnchecked
          ]}
        />
      </View>
    </Pressable>
  );
}

